<?phpnamespace App\Console\Commands\Mqtt;use App\Models\Device;use Illuminate\Console\Command;use PhpMqtt\Client\Facades\MQTT;class MqttWorker extends Command{    /**     * The name and signature of the console command.     *     * @var string     */    protected $signature = 'app:mqtt-worker';    /**     * The console command description.     *     * @var string     */    protected $description = 'Command description';    /**     * Execute the console command.     */    public function handle(): void    {        try {            $mqtt = MQTT::connection();            $mqtt->subscribe('device/+/status', function (string $topic, string $message) {                $this->handleDeviceStatus($topic, $message);            });            /*$mqtt->subscribe('device/+/state/irrigation', function (string $topic, string $message) {                $this->handleDeviceIrrigationState($topic, $message);            });*/            $mqtt->subscribe('device/+/response', function (string $topic, string $message) {                $this->handleDeviceResponse($topic, $message);            });            $mqtt->subscribe('device/+/history-irrigation', function (string $topic, string $message) {                $this->handlePlantWateringLog($topic, $message);            });            $mqtt->loop();        } catch (\Throwable $e) {            sleep(10);        }    }    /**     * Device Status Handler     * */    private function handleDeviceStatus(string $topic, string $message): void    {        // Todo: Handle device status changes here        $topic = $this->parseTopic($topic);        logs();        $data = json_decode($message, true);        if ($device = Device::find($topic['id'])) {            $device->status = (bool)$data['status'];            $device->save();        }    }    /**     * Device Irrigation State Handler     * */    private function handleDeviceIrrigationState(string $topic, string $message): void    {        // Todo: Handle device irrigation status changes here        $topic = $this->parseTopic($topic);        $data = json_decode($message, true);        if ($device = Device::find($topic['id'])) {            // Simpan dalam integer langsung dari esp32            $device->irrigation_state = (int)$data['irrigation_state'];            $device->save();        }    }    /**     * Device Ai State Handler     * */    private function handleDeviceResponse(string $topic, string $message): void    {        // Todo: Handle device ai status changes here        $topic = $this->parseTopic($topic);        $data = json_decode($message, true);        $updated = false;        if ($device = Device::find($topic['id'])) {            if ($data["cmd"] == "ai") {                $device->ai_status = (bool)$data['data']['status'];                $updated = true;            }            if ($data["cmd"] == "mi") {                $device->irrigation_state = (int)$data['data']['state'];                $updated = true;            }        }        if ($updated) {            $device->save();        }    }    private function handlePlantWateringLog(string $topic, string $message): void    {        $topic = $this->parseTopic($topic);        $data = json_decode($message, true);        if (!$data) return;    }    private function parseTopic(string $topic): array    {        $parts = explode('/', $topic);        return [            'id' => $parts[1] ?? null,            'state_type' => $parts[3] ?? null        ];    }}